import os
for r,d,fs in os.walk('studies'):
 for f in fs: print(os.path.join(r,f))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 for l in gzip.open(f,'rt'):
  if l.startswith('!Series_') or l.startswith(('!Sample_title','!Sample_source_name','!Sample_characteristics','!Sample_treatment','!Sample_growth')): print(l[:28000].strip())

import gzip,glob,csv,collections
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 for l in gzip.open(f,'rt'):
  if l.startswith(('!Sample_treatment','!Sample_growth','!Sample_characteristics','!Sample_title')):
   a=next(csv.reader([l],delimiter='\t')); print(a[0],dict(collections.Counter(a[1:])))

